class UnknownName(KeyError):
    """A name the registry does not hold."""


class TreeReadError(OSError):
    """A git tree could not be read: an unknown revision, no git, or not a repo."""


class LayoutError(OSError):
    """A path would leave the repo: .broomva/ or .control/ is a symlink, or the entry a
    name resolves to is (on disk, or as a committed symlink in a tree)."""



def _scoped(name: str, scopes: Sequence[str]) -> str:
    """``name`` without one leading scope from ``scopes``."""
    for scope in scopes:
        if name.startswith(scope + "."):
            return name[len(scope) + 1:]
    return name


def _repo_entry(name: str) -> Tuple[str, bool, bool]:
    key = _scoped(name, ("repo", "workspace"))
    if key not in REPO:
        raise UnknownName(name)
    return REPO[key]


def _state_entry(name: str) -> Optional[str]:
    """The path of a repo runtime-state name, or None when ``name`` is not one."""
    return REPO_STATE.get(_scoped(name, ("repo", "workspace")))


def repo_key(root: os.PathLike) -> str:
    """A repo's name in machine state: its top-level folder name plus the first 12 hex
    digits of the sha256 of its real path, so two checkouts both called `checkout`
    never share state. `_root` stands in for the name of `/`."""
    root = _require_root(root)
    # The real path of the nearest existing folder, then the rest as named: the same key
    # before the folder exists (a workspace not cloned yet) and after. A dangling symlink
    # on the way up is refused: it names a place that does not exist (both readers agree).
    probe = Path(os.path.abspath(str(root)))
    while not os.path.exists(probe) and probe != probe.parent:
        if os.path.islink(probe):
            raise ValueError(f"{probe} is a dangling symlink above the repo root {root}")
        probe = probe.parent
    real = os.path.realpath(root)
    name = Path(real).name or "_root"
    return f"{name}-{hashlib.sha256(real.encode()).hexdigest()[:12]}"


def state_dir(root: os.PathLike) -> Path:
    """Where a repo's runtime state lives once moved: $BROOMVA_HOME/state/repos/<repo_key>."""
    return machine_root() / "state" / "repos" / repo_key(root)


def _machine_entry(name: str) -> Tuple[str, Optional[str]]:
    key = _scoped(name, ("machine",))
    if key not in MACHINE:
        raise UnknownName(name)
    return MACHINE[key]


def _home() -> Path:
    """$HOME when set and non-empty, else the account's home: the shell reader's rule.
    A relative $HOME is refused: every root built on it would follow the cwd."""
    value = os.environ.get("HOME")
    if value:
        home = Path(value)
    else:
        try:
            account = pwd.getpwuid(os.getuid())
        except KeyError as e:
            raise ValueError("HOME is empty and this account has no home in the password database") from e
        # The shell reader's rule for the account name (it reaches eval there): a letter or _ first.
        name = account.pw_name
        if not name or not (name[0].isascii() and (name[0].isalpha() or name[0] == "_")) \
                or any(not (c.isascii() and (c.isalnum() or c in "._@-")) for c in name):
            raise ValueError(f"HOME is empty and the account name {name!r} cannot be used to find a home")
        home = Path(account.pw_dir)
    if not home.is_absolute():
        raise ValueError(f"HOME must be an absolute path: {value!r}")
    return _norm(home)


def _norm(path: Path) -> Path:
    """normpath, with a leading `//` collapsed as the shell reader collapses it (on macOS
    and Linux `//` names the root; POSIX leaves it implementation-defined)."""
    p = os.path.normpath(str(path))
    return Path("/" + p.lstrip("/")) if p.startswith("//") else Path(p)


def _same(a: Path, b: Path) -> bool:
    """One folder: equal once normalized (so two paths that do not exist yet compare
    too), or the same file by identity (case, links)."""
    if os.path.normpath(str(a)) == os.path.normpath(str(b)):
        return True
    try:
        return os.path.samefile(a, b)
    except OSError:
        return False


def _expand(value: str) -> Path:
    """A leading ~ or ~/ becomes the home; ~user is refused (the shell reader cannot
    look up another account the same way); a trailing slash is dropped."""
    if value == "~":
        return _home()
    if value.startswith("~/"):
        return _home() / value[2:]
    if value.startswith("~"):
        raise ValueError(f"~user paths are not supported: {value!r}")
    return Path(value)


def _absolute(key: str, value: str) -> Path:
    path = _expand(value)
    if not path.is_absolute():
        raise ValueError(f"{key} must be an absolute path (or start with ~/): {value!r}")
    return _norm(path)  # `..` and `.` collapse, as in the shell reader


def machine_root() -> Path:
    value = os.environ.get(MACHINE_ENV)
    return _absolute(MACHINE_ENV, value) if value else _expand(MACHINE_DEFAULT)


def workspace_root() -> Path:
    root = None
    for key in WORKSPACE_ENV:
        value = os.environ.get(key)
        if value:
            root = _absolute(key, value)
            break
    if root is None:
        root = _expand(WORKSPACE_DEFAULT)
    if _same(root, _home()):
        raise ValueError(f"the workspace root cannot be $HOME: {root} (workspace.* would land in the machine root)")
    return root


def _git(args: List[str]) -> subprocess.CompletedProcess:
    env = {k: v for k, v in os.environ.items() if k not in ("GIT_DIR", "GIT_WORK_TREE")}
    return subprocess.run(["git", *args], capture_output=True, text=True, timeout=GIT_TIMEOUT, check=False, env=env)


def _exists(path: Path) -> bool:
    """Path.exists(), except that only "not there" is False. An unreadable folder
    raises (Python 3.12+ would return False, and a check would read it as clean)."""
    try:
        path.stat()
    except (FileNotFoundError, NotADirectoryError):
        return False
    return True


def _require_root(root: Optional[os.PathLike]) -> Path:
    if root is None or str(root) == "":
        raise ValueError("a repo root is required (an empty one would mean the cwd)")
    if ".." in Path(str(root)).parts:
        raise ValueError(f"a repo root has no `..` part (a git top level never does): {root}")
    return Path(root)


def _lstat(path: Path) -> Optional[os.stat_result]:
    """lstat, None only when the path is not there. Anything else raises: Python 3.12+
    Path.is_symlink() answers False when lstat is denied, which would pass a link."""
    try:
        return os.lstat(path)
    except (FileNotFoundError, NotADirectoryError):
        return None


def _contained(root: Path) -> None:
    """Refuse a repo whose .broomva/ or .control/ is anything but a real, searchable
    folder: a symlink sends every path under it outside the repo, a file holds nothing,
    and an unsearchable folder cannot be answered for."""
    for folder in (REPO_DIR, REPO_LEGACY_DIR):
        info = _lstat(root / folder)
        if info is None:
            continue
        if stat.S_ISLNK(info.st_mode):
            raise LayoutError(f"{root / folder} is a symlink; it must be a real folder in the repo")
        if not stat.S_ISDIR(info.st_mode):
            raise LayoutError(f"{root / folder} is not a folder")
        if not os.access(root / folder, os.X_OK):
            raise PermissionError(f"{root / folder} cannot be searched")


def _entry(path: Path, owner: bool = False) -> Path:
    """``path`` if it is safe to return: absent, or a real file or folder (and, for an
    owner-written file, a single link). A dangling symlink is refused too."""
    info = _lstat(path)
    if info is None:
        return path
    if stat.S_ISLNK(info.st_mode):
        raise LayoutError(f"{path} is a symlink; a registry entry is a real file or folder")
    if not (stat.S_ISREG(info.st_mode) or stat.S_ISDIR(info.st_mode)):
        raise LayoutError(f"{path} is neither a file nor a folder")
    if owner and stat.S_ISREG(info.st_mode) and info.st_nlink > 1:
        raise LayoutError(f"{path} has {info.st_nlink} links; an owner-written file has one")
    return path


def _toplevel(target: Path) -> Optional[Path]:
    """The git top level of ``target``. git starts from the nearest ancestor that is a
    real folder: a folder about to be created does not exist yet, and a symlinked one
    (`.broomva -> elsewhere`) would take git out of the repo. Raises TreeReadError
    when git cannot run, so "no git" is never read as "not a repo"."""
    # os.path.isdir / islink never raise: an unsearchable folder is walked past, as in the shell reader.
    directory = target if (os.path.isdir(target) and not os.path.islink(target)) else target.parent
    while (os.path.islink(directory) or not os.path.isdir(directory)) and directory != directory.parent:
        directory = directory.parent
    try:
        out = _git(["-C", str(directory), "rev-parse", "--show-toplevel"])
    except (OSError, subprocess.SubprocessError) as e:
        raise TreeReadError(f"git could not run: {e}") from e
    if out.returncode != 0 or not out.stdout.strip():
        return None
    top = Path(out.stdout.strip())
    try:
        at_home = os.path.samefile(top, _home())  # the same folder, whatever its case or links
    except OSError:
        at_home = False
    if at_home:
        return None  # a git repo at $HOME would make the repo and machine scopes coincide
    return top


def repo_root(target: Optional[os.PathLike] = None) -> Optional[Path]:
    """The repo a tool operates on: the git top level of ``target``, else of
    $CLAUDE_PROJECT_DIR, else None. Never the cwd: an empty target is no target.
    Raises TreeReadError when git cannot run."""
    if target is not None and str(target) != "":
        return _toplevel(Path(target))
    project = os.environ.get("CLAUDE_PROJECT_DIR")
    return _toplevel(Path(project)) if project else None


def repo_rels(name: str) -> Tuple[str, ...]:
    """The repo-relative paths a name may hold, new first: for tree reads and gates.
    Runtime state leaves the repo when it moves, so only its legacy path is in-repo."""
    state = _state_entry(name)
    if state is not None:
        return (f"{REPO_LEGACY_DIR}/{state}",)
    path, legacy, _ = _repo_entry(name)
    new = f"{REPO_DIR}/{path}"
    return (new, f"{REPO_LEGACY_DIR}/{path}") if legacy else (new,)


def moved(root: os.PathLike) -> bool:
    """Whether the repo at ``root`` has moved: any name that has a legacy location
    is already under .broomva/. A .control/ left behind (untracked runtime files
    survive a pull) then no longer draws new files back."""
    root = _require_root(root)
    _contained(root)
    found = [(root / REPO_DIR / path, owner) for path, legacy, owner in REPO.values() if legacy]
    found = [(p, owner) for p, owner in found if _lstat(p) is not None]
    for p, owner in found:
        _entry(p, owner)
    return bool(found)


def partially_moved(root: os.PathLike) -> List[str]:
    """Names still under .control/ in a repo that has moved. One stray file under
    .broomva/ marks a repo moved, and from then on new files go there while these
    stay behind: the ledgers split, and no name is under both roots to show it."""
    root = _require_root(root)
    if not moved(root):
        return []
    return [name for name, (path, legacy, _) in REPO.items() if legacy and _exists(root / REPO_LEGACY_DIR / path)]


def repo_path(name: str, root: os.PathLike) -> Path:
    """Where ``name`` lives on disk in the repo at ``root`` (see the migration rule).
    ``root`` is the repo's top level, as repo_root() returns it."""
    state = _state_entry(name)
    if state is not None:
        root = _require_root(root)
        _contained(root)
        new, old = state_dir(root) / state, root / REPO_LEGACY_DIR / state
        if _exists(new) or _lstat(new) is not None:
            return _entry(new)
        if _exists(old) or _lstat(old) is not None or ((root / REPO_LEGACY_DIR).is_dir() and not moved(root)):
            return _entry(old)
        return _entry(new)
    path, legacy, owner = _repo_entry(name)
    root = _require_root(root)
    _contained(root)
    new = root / REPO_DIR / path
    old = root / REPO_LEGACY_DIR / path
    if not legacy or _exists(new) or _lstat(new) is not None:
        return _entry(new, owner)
    if _exists(old) or _lstat(old) is not None or ((root / REPO_LEGACY_DIR).is_dir() and not moved(root)):
        return _entry(old, owner)
    return _entry(new, owner)


def workspace_path(name: str) -> Path:
    return repo_path(name, workspace_root())


def machine_path(name: str) -> Path:
    path, legacy = _machine_entry(name)
    new = machine_root() / path
    if legacy is None or _exists(new):
        return new
    old = _expand(legacy)
    return old if _exists(old) else new


def tree_path(name: str, root: os.PathLike, rev: str = "HEAD") -> Optional[str]:
    """The repo-relative path ``name`` has in git tree ``rev`` of the repo at
    ``root``, new before legacy; None when the tree holds neither. Raises
    TreeReadError when the tree cannot be read at all."""
    rels = repo_rels(name)
    root = _require_root(root)
    if not rev or rev.startswith("-"):
        raise ValueError(f"not a revision: {rev!r}")
    try:
        ok = _git(["-C", str(root), "rev-parse", "--verify", "--quiet", f"{rev}^{{tree}}"])
        if ok.returncode != 0:
            raise TreeReadError(f"cannot read revision {rev!r} in {root}")
        _tree_contained(root, rev)
        for rel in rels:
            out = _git(["-C", str(root), "ls-tree", "--full-tree", "-z", rev, "--", rel])
            if out.returncode != 0:
                raise TreeReadError(f"git ls-tree failed in {root}: {out.stderr.strip()}")
            for line in out.stdout.split("\0"):
                meta, _, entry = line.partition("\t")
                if entry == rel:
                    mode = meta.split(" ", 1)[0]
                    if mode not in ("040000", "100644", "100755"):
                        raise LayoutError(f"{rel} is not a folder or a file in {rev} (mode {mode})")
                    return rel
    except (OSError, subprocess.SubprocessError) as e:
        if isinstance(e, (TreeReadError, LayoutError)):
            raise
        raise TreeReadError(f"git could not run in {root}: {e}") from e
    return None


def _tree_contained(root: Path, rev: str) -> None:
    """.broomva and .control in tree ``rev`` are folders: never a committed symlink, file or gitlink."""
    out = _git(["-C", str(root), "ls-tree", "--full-tree", "-z", rev, "--", REPO_DIR, REPO_LEGACY_DIR])
    if out.returncode != 0:
        raise TreeReadError(f"git ls-tree failed in {root}: {out.stderr.strip()}")
    for line in out.stdout.split("\0"):
        meta, _, entry = line.partition("\t")
        if entry in (REPO_DIR, REPO_LEGACY_DIR) and not meta.startswith("040000 "):
            raise LayoutError(f"{entry} is not a folder in {rev} ({meta.split(' ', 1)[0]})")


def _tree_entries(root: Path, rev: str, folder: str) -> List[str]:
    out = _git(["-C", str(root), "ls-tree", "--full-tree", "--name-only", "-z", rev, "--", folder + "/"])
    if out.returncode != 0:
        raise TreeReadError(f"git ls-tree failed in {root}: {out.stderr.strip()}")
    return [e[len(folder) + 1:] for e in out.stdout.split("\0") if e.startswith(folder + "/")]


def shadowed(root: os.PathLike, rev: Optional[str] = None) -> List[str]:
    """Names present under both roots, where the prefer-new rule would hide the
    legacy copy: on disk, or in git tree ``rev`` (a branch cut before the move,
    such as maestro/answers, recreates .control/ entries). Raises OSError (on
    disk; LayoutError for a symlinked root) or TreeReadError (in a tree) when a
    root cannot be read."""
    root = _require_root(root)
    if rev is not None:
        if not rev or rev.startswith("-"):
            raise ValueError(f"not a revision: {rev!r}")
        try:
            ok = _git(["-C", str(root), "rev-parse", "--verify", "--quiet", f"{rev}^{{tree}}"])
            if ok.returncode != 0:
                raise TreeReadError(f"cannot read revision {rev!r} in {root}")
            _tree_contained(root, rev)
            new, old = set(_tree_entries(root, rev, REPO_DIR)), set(_tree_entries(root, rev, REPO_LEGACY_DIR))
        except (OSError, subprocess.SubprocessError) as e:
            if isinstance(e, (TreeReadError, LayoutError)):
                raise
            raise TreeReadError(f"git could not run in {root}: {e}") from e
        return [name for name, (path, legacy, _) in REPO.items() if legacy and path in new and path in old]
    _contained(root)
    new_root, old_root = root / REPO_DIR, root / REPO_LEGACY_DIR
    names = [
        name for name, (path, legacy, _) in REPO.items()
        if legacy and _exists(new_root / path) and _exists(old_root / path)
    ]
    state = state_dir(root)
    return names + [name for name, path in REPO_STATE.items() if _exists(state / path) and _exists(old_root / path)]


def resolve(name: str, root: Optional[os.PathLike] = None) -> Path:
    """Resolve a scoped name: ``repo.X`` (needs ``root``), ``workspace.X`` or ``machine.X``."""
    if name.startswith("machine."):
        return machine_path(name)
    if name.startswith("workspace."):
        return workspace_path(name)
    if name.startswith("repo."):
        if root is None:
            raise ValueError("a repo name needs a root")
        return repo_path(name, root)
    raise UnknownName(name)


def all_names() -> List[str]:
    repo = list(REPO) + list(REPO_STATE)
    return [f"repo.{n}" for n in repo] + [f"workspace.{n}" for n in repo] + [f"machine.{n}" for n in MACHINE]


EPILOG = """exit codes: 0 found or clean; 1 absent (tree), or names shadowed; 2 usage error or
unknown name; 3 could not read (unknown revision, no git, not a repo, unreadable folder).
names take a scope: repo.NAME, workspace.NAME or machine.NAME (see `list`)."""


def main(argv: Optional[List[str]] = None) -> int:
    parser = argparse.ArgumentParser(prog="broomva_paths.py", description="The Broomva path registry.",
                                     epilog=EPILOG, formatter_class=argparse.RawDescriptionHelpFormatter)
    sub = parser.add_subparsers(dest="cmd", required=True)
    p = sub.add_parser("resolve", help="print where a scoped name lives on disk")
    p.add_argument("name")
    p.add_argument("--root", help="a path inside the repo (for repo.* names)")
    p = sub.add_parser("tree", help="print the path a repo name has in a git tree")
    p.add_argument("name")
    p.add_argument("--root", required=True)
    p.add_argument("--rev", default="HEAD")
    p = sub.add_parser("rels", help="print the repo-relative paths a name may hold")
    p.add_argument("name")
    p = sub.add_parser("shadowed", help="print names present under both roots of a repo")
    p.add_argument("--root", required=True)
    p.add_argument("--rev", help="look in this git tree instead of on disk")
    p = sub.add_parser("split", help="print names still under .control/ in a repo that has moved")
    p.add_argument("--root", required=True)
    p = sub.add_parser("root", help="print a scope's root: workspace or machine")
    p.add_argument("scope", choices=["workspace", "machine"])
    p = sub.add_parser("check", help="resolve every name; exit 0 when all resolve")
    p.add_argument("--root", required=True, help="a repo to resolve repo.* names in")
    sub.add_parser("hash", help="print the embedded registry sha256")
    sub.add_parser("list", help="print every scoped name")
    args = parser.parse_args(argv)
    try:
        if args.cmd == "resolve":
            root = None
            if args.name.startswith("repo."):
                root = repo_root(args.root) if args.root else repo_root()
                if root is None:
                    where = f"{args.root} is not inside a git repo, or its top level is $HOME" if args.root \
                        else "no repo: pass --root, or set CLAUDE_PROJECT_DIR"
                    print(where, file=sys.stderr)
                    return EXIT_USAGE
            print(resolve(args.name, root))
        elif args.cmd == "tree":
            rel = tree_path(args.name, args.root, args.rev)
            if rel is None:
                return EXIT_ABSENT
            print(rel)
        elif args.cmd == "rels":
            print("\n".join(repo_rels(args.name)))
        elif args.cmd == "shadowed":
            names = shadowed(args.root, args.rev)
            if names:
                print("\n".join(names))
            return EXIT_ABSENT if names else EXIT_OK
        elif args.cmd == "check":
            if not Path(args.root).is_dir():
                raise FileNotFoundError(f"no such folder: {args.root}")
            for name in all_names():
                resolve(name, args.root)
        elif args.cmd == "split":
            names = partially_moved(args.root)
            if names:
                print("\n".join(names))
            return EXIT_ABSENT if names else EXIT_OK
        elif args.cmd == "root":
            print(workspace_root() if args.scope == "workspace" else machine_root())
        elif args.cmd == "hash":
            print(REGISTRY_SHA256)
        elif args.cmd == "list":
            print("\n".join(all_names()))
    except UnknownName as e:
        print(f"unknown name: {e.args[0]} (names take a scope: repo., workspace. or machine.)", file=sys.stderr)
        return EXIT_USAGE
    except ValueError as e:
        print(str(e), file=sys.stderr)
        return EXIT_USAGE
    except OSError as e:
        print(f"could not read: {e}", file=sys.stderr)
        return EXIT_UNREADABLE
    return EXIT_OK


if __name__ == "__main__":
    sys.exit(main())
